/* The next Power Play: the first Wednesday of the month, from the same function
   that dates the confirmation email (mailer.php), so the page and the email agree.
   site-life.js recounts the days on the visitor's own clock. */
$pp = (function (): array {
    $n = mam_powerplay_next()['dt'];
    $today = new DateTimeImmutable('today', $n->getTimezone());
    $days = (int) $today->diff($n->setTime(0, 0))->days;
    return ['days' => $days === 0 ? 'Today' : (string) $days,
            'unit' => $days === 0 ? 'Join us this evening' : ($days === 1 ? 'day to go' : 'days to go'),
            'date' => $n->format('l j F')];
})();
